import{_ as d,o as r,c as a,ae as e}from"./chunks/framework.DJK_dC0-.js";const p=JSON.parse('{"title":"诊断与掌握合同","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/diagnostic.md","filePath":"tutorial/diagnostic.md"}'),o={name:"tutorial/diagnostic.md"};function i(l,t,n,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="诊断与掌握合同" tabindex="-1">诊断与掌握合同 <a class="header-anchor" href="#诊断与掌握合同" aria-label="Permalink to &quot;诊断与掌握合同&quot;">​</a></h1><p>本课程不把读完页面、点击运行或自评当作掌握。每次学习前后都记录可观察证据，并用五个维度更新路线：</p><ul><li><strong>Explain</strong>：能说清因果、不变量、边界和反例。</li><li><strong>Perform</strong>：从新起点独立完成一个小而真实的任务。</li><li><strong>Debug</strong>：定位陌生缺陷，说明信号、根因和最小修复。</li><li><strong>Transfer</strong>：改变语言、工具、约束或业务场景后仍能使用同一机制。</li><li><strong>Retain</strong>：延迟后无提示重建，未复测前状态只能是 fragile。</li></ul><h2 id="首轮高信息量探针" tabindex="-1">首轮高信息量探针 <a class="header-anchor" href="#首轮高信息量探针" aria-label="Permalink to &quot;首轮高信息量探针&quot;">​</a></h2><table tabindex="0"><thead><tr><th>探针</th><th>任务</th><th>主要区分</th></tr></thead><tbody><tr><td>P1</td><td>用 Python 写一个安全的 <code>get_or_default</code>，处理列表、字典和空值</td><td>语法、可变对象、默认参数</td></tr><tr><td>P2</td><td>解释 JS Promise 与 Python coroutine 的执行边界，并写一个超时示例</td><td>异步心智模型</td></tr><tr><td>P3</td><td>给出一段缺少 <code>tool_call_id</code> 对齐的 Agent Loop，定位并修复错误</td><td>协议、数据结构、调试</td></tr><tr><td>P4</td><td>用固定 corpus 计算 hit rate、recall@3 和 MRR</td><td>数据类、函数分解、评测</td></tr><tr><td>P5</td><td>设计一个只读知识库工具的权限、审计和拒答边界</td><td>业务建模、安全、迁移</td></tr><tr><td>P6</td><td>在检索命中下降后判断是切块、召回、重排还是评测集问题</td><td>诊断策略与可观测性</td></tr></tbody></table><p>探针只覆盖会改变前两步路线的共享先修；通过 P1 不会自动跳过 P3 或 P5。</p><h2 id="状态规则" tabindex="-1">状态规则 <a class="header-anchor" href="#状态规则" aria-label="Permalink to &quot;状态规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>判定</th></tr></thead><tbody><tr><td>unseen</td><td>没有表现证据</td></tr><tr><td>blocked</td><td>缺环境、权限或硬先修</td></tr><tr><td>learning</td><td>正在练习或明显依赖提示</td></tr><tr><td>fragile</td><td>立即任务通过，但解释、调试、迁移或延迟保持不足</td></tr><tr><td>mastered</td><td>四维无提示通过且延迟保持验证</td></tr></tbody></table><h2 id="反馈合同" tabindex="-1">反馈合同 <a class="header-anchor" href="#反馈合同" aria-label="Permalink to &quot;反馈合同&quot;">​</a></h2><p>每次失败输出：</p><ol><li>观察到的证据；</li><li>主要错误类型：concept / procedure / strategy / attention / tool / environment；</li><li>只解释一个最小关键机制；</li><li>一个更小的修复任务；</li><li>一道去掉支架的同构题；</li><li>下一次复测的通过标准。</li></ol><p>LLM 可以生成反馈建议，但不能仅凭对话或自评修改 canonical mastery state。</p>',12)])])}const u=d(o,[["render",i]]);export{p as __pageData,u as default};
